text:
1.9 Comparando modelos: viés, sobreajuste e validação cruzada
Como vários modelos podem representar a mesma realidade, precisamos compará-los. Neste livro, o melhor modelo é, por padrão, aquele que melhor representa a realidade que pretende aproximar para o propósito em questão, e medimos isso com métricas de desempenho calculadas em dados que o modelo não viu (James et al. 2021, cap. 2). No aprendizado supervisionado, as métricas medem a distância entre as predições e os desfechos observados (erro absoluto médio, acurácia, área sob a curva ROC…); no aprendizado não supervisionado, medem o quanto a estrutura é bem capturada (silhueta, erro de reconstrução); no aprendizado por reforço, a recompensa acumulada; na modelagem generativa, a fidelidade, a diversidade e a segurança do que é gerado. Cada capítulo apresenta as métricas de que precisa. O desempenho preditivo não é o único critério: também valorizamos modelos que possam ser interpretados e usados para responder a perguntas científicas (Capítulo 12), e uma boa análise busca um equilíbrio.

Definição 1.8 (Viés, variância, sobreajuste) Um modelo tem viés alto quando os seus pressupostos são rígidos demais para capturar o padrão real: ele fica subajustado (underfitting) e erra sistematicamente. Tem variância alta quando é tão flexível que acompanha o ruído do seu conjunto de treino específico: ele sofre sobreajuste (overfitting), com desempenho excelente no treino e fraco em dados novos. Bons modelos equilibram os dois (James et al. 2021, cap. 2).







Figura 1.9: Uma poltrona moldada para servir perfeitamente a uma única criança. Ela é ideal para essa criança e desconfortável, ou inútil, para qualquer outra: um modelo sobreajustado fica sob medida para os dados de treino da mesma maneira.



Pense numa poltrona feita sob medida para uma criança (Figura 1.9): ela se ajusta a cada curva daquela criança, e de mais ninguém. Um modelo sobreajustado foi moldado em torno dos pacientes específicos com que foi treinado, inclusive das suas peculiaridades acidentais, e se ajusta mal a pacientes novos.

Simples demais, na medida certa, flexível demais. Trinta pontos de treino vêm de uma curva suave (tracejada) somada a ruído. O modelo é um polinômio cujo grau você escolhe: grau 1 é uma reta; graus altos fazem muitas curvas. Observe o erro de treino e o erro em 300 pontos de teste novos.

viewof deg = Inputs.range([0, 15], {value: 1, step: 1, label: "Grau do polinômio"})







ofit = {
  function mulberry32(a) { return function() { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a &gt;&gt;&gt; 15, 1 | a); t = t + Math.imul(t ^ t &gt;&gt;&gt; 7, 61 | t) ^ t; return ((t ^ t &gt;&gt;&gt; 14) &gt;&gt;&gt; 0) / 4294967296; }; }
  const rnd = mulberry32(42);
  const gauss = () =&gt; { let u = 0, v = 0; while (u === 0) u = rnd(); v = rnd(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v); };
  const truth = x =&gt; Math.sin(3 * x) + 0.3 * x;
  const sample = m =&gt; d3.range(m).map(() =&gt; { const x = rnd() * 2 - 1; return {x, y: truth(x) + 0.35 * gauss()}; });
  const train = sample(30), test = sample(300);
  const cheb = (x, d) =&gt; { const T = [1, x]; for (let k = 2; k &lt;= d; k++) T.push(2 * x * T[k - 1] - T[k - 2]); return T.slice(0, d + 1); };
  function fit(d) {
    const m = d + 1, A = d3.range(m).map(() =&gt; new Array(m).fill(0)), bv = new Array(m).fill(0);
    for (const p of train) { const t = cheb(p.x, d); for (let i = 0; i &lt; m; i++) { bv[i] += t[i] * p.y; for (let j = 0; j &lt; m; j++) A[i][j] += t[i] * t[j]; } }
    for (let i = 0; i &lt; m; i++) A[i][i] += 1e-9;
    for (let c = 0; c &lt; m; c++) { let piv = c; for (let r = c + 1; r &lt; m; r++) if (Math.abs(A[r][c]) &gt; Math.abs(A[piv][c])) piv = r;
      [A[c], A[piv]] = [A[piv], A[c]]; [bv[c], bv[piv]] = [bv[piv], bv[c]];
      for (let r = 0; r &lt; m; r++) if (r !== c) { const f = A[r][c] / A[c][c]; for (let k = c; k &lt; m; k++) A[r][k] -= f * A[c][k]; bv[r] -= f * bv[c]; } }
    const w = bv.map((v, i) =&gt; v / A[i][i]);
    const pred = x =&gt; cheb(x, d).reduce((s, t, i) =&gt; s + t * w[i], 0);
    const rmse = data =&gt; Math.sqrt(d3.mean(data, p =&gt; (p.y - pred(p.x)) ** 2));
    return {pred, train: rmse(train), test: rmse(test)};
  }
  const all = d3.range(0, 16).map(d =&gt; ({d, ...fit(d)}));
  return {train, truth, all};
}







{
  const cur = ofit.all[deg];
  const grid = d3.range(-1, 1.0001, 0.01);
  const verdict = deg &lt;= 2 ? "viés alto: simples demais para acompanhar a curva" : deg &lt;= 6 ? "um equilíbrio razoável" : "variância alta: perseguindo o ruído";
  return html`&lt;p&gt;Grau ${deg}: erro de treino &lt;strong&gt;${cur.train.toFixed(3)}&lt;/strong&gt; · erro de teste &lt;strong&gt;${cur.test.toFixed(3)}&lt;/strong&gt; — ${verdict}.&lt;/p&gt;`;
}







Plot.plot({
  height: 260, grid: true, y: {domain: [-2.5, 2.5], label: "y"}, x: {label: "x"},
  marks: [
    Plot.line(d3.range(-1, 1.0001, 0.01).map(x =&gt; [x, ofit.truth(x)]), {strokeDasharray: "5,4"}),
    Plot.line(d3.range(-1, 1.0001, 0.005).map(x =&gt; [x, Math.max(-2.5, Math.min(2.5, ofit.all[deg].pred(x)))]), {stroke: "#1f6f8b", strokeWidth: 2.5}),
    Plot.dot(ofit.train, {x: "x", y: "y", r: 3, fill: "currentColor"})
  ]
})







Plot.plot({
  height: 200, grid: true, x: {label: "Grau do polinômio"}, y: {label: "Erro (RMSE)", domain: [0, 1.2]},
  color: {legend: true, domain: ["treino", "teste"], range: ["#888", "#1f6f8b"]},
  marks: [
    Plot.line(ofit.all, {x: "d", y: d =&gt; Math.min(d.train, 1.2), stroke: () =&gt; "treino", strokeWidth: 2}),
    Plot.line(ofit.all, {x: "d", y: d =&gt; Math.min(d.test, 1.2), stroke: () =&gt; "teste", strokeWidth: 2}),
    Plot.ruleX([deg], {strokeDasharray: "3,3"})
  ]
})







O erro de treino sempre cai à medida que o modelo fica mais flexível; o erro de teste cai e depois volta a subir. O grau com o menor erro de teste é o que deve ser escolhido. Mas usamos o conjunto de teste para fazer essa escolha — então ele já não é um juiz honesto do modelo escolhido. A solução padrão é a validação cruzada.

Definição 1.9 (Validação cruzada) Na validação cruzada com \(V\) partições (\(V\)-fold), os dados de treino são divididos em \(V\) partes (partições). Cada partição, por sua vez, é deixada de fora enquanto o modelo é ajustado nas outras \(V-1\) partições e avaliado na partição separada; os \(V\) erros são então promediados. Escolhas como o grau do polinômio são feitas com o erro de validação cruzada, e o conjunto de teste é usado uma única vez, no final. Com \(V = n\), ela se chama validação cruzada leave-one-out (deixando um de fora) (Stone 1974; James et al. 2021, cap. 5).



  Validação cruzada com cinco partições
  Cinco linhas, uma por rodada. Em cada linha, os dados de treino são desenhados como cinco blocos; um bloco diferente em cada linha é separado para validação e os outros quatro são usados no ajuste.

  Rodada 1Rodada 2Rodada 3Rodada 4Rodada 5








  separada

Validação cruzada com cinco partições: cada partição (em destaque) é separada uma vez enquanto o modelo é ajustado nas outras quatro.

Viés, sobreajuste e validação cruzada tratam de uma mesma pergunta: o modelo está aprendendo o sinal ou memorizando o ruído? Respondê-la com honestidade é o que torna um modelo apto a embasar decisões reais. O Capítulo 3 transforma essas ideias em uma rotina de trabalho.

Sua primeira avaliação honesta. Use a divisão fixa do livro dos dados da UTI Ala 7 em um conjunto de treino (1.000 pacientes, 80 %) e um de teste (250 pacientes, 20 %) e depois avalie o modelo mais simples possível: prever, para cada paciente de teste, a variação média da creatinina dos pacientes de treino. Preencha a lacuna com a função que calcula uma média. A última linha calcula o erro absoluto médio no conjunto de teste.

RPython

















A função que calcula a média aritmética no R é mean().


prediction &lt;- mean(train$delta_creatinine_48h)


















As colunas do pandas têm um método .mean().


prediction = train["delta_creatinine_48h"].mean()




R e Python leem a mesma divisão, então ambos dão 0,236 mg/dL. Esta é a primeira linha da tabela de comparação que o Capítulo 3 inicia e que todos os capítulos seguintes ampliam: cada novo modelo da UTI Ala 7 é julgado nesses mesmos 250 pacientes de teste.

3.5 Validação cruzada, passo a passo
O Capítulo 1 definiu a validação cruzada com \(V\) partições (Definição 1.9); eis o procedimento completo (Stone 1974; James et al. 2021, cap. 5). Pegue o conjunto de treino, já dividido em \(V\) partições de tamanho aproximadamente igual (na UTI Ala 7, \(V = 5\) partições de 200). Então, para cada partição \(v = 1, \dots, V\):

separe a partição \(v\) como a partição de validação;
ajuste o modelo nas outras \(V - 1\) partições, incluindo todas as etapas que dependem dos dados (escolher variáveis, padronizar, imputar; veja a Seção 3.6);
preveja os desfechos da partição de validação e calcule a métrica, \(\text{MAE}_v\).

Por fim, faça a média dos \(V\) resultados:
\[
\text{CV}_{(V)} = \frac{1}{V}\sum_{v=1}^{V} \text{MAE}_v .
\qquad(3.6)\]
Cada paciente de treino é usado na validação exatamente uma vez e no ajuste \(V - 1\) vezes. A dispersão dos \(V\) erros das partições diz o quanto a estimativa mudaria com outra divisão; seu erro padrão, o desvio padrão dos erros das partições dividido por \(\sqrt{V}\), é uma medida aproximada dessa incerteza (Hastie, Tibshirani, e Friedman 2009, cap. 7).

Veja a validação cruzada acontecer. Cada ponto é um dos 1.000 pacientes de treino da UTI Ala 7. Em cada rodada, uma partição (colorida) é separada, o modelo é ajustado nas outras quatro (cinza) e seu MAE é calculado na partição separada. A rodada 6 combina os cinco resultados. Escolha um modelo e depois aperte Reproduzir ou mova o controle deslizante. Repare que o conjunto de teste nunca participa.

icu3 = FileAttachment("data/icu_aki.csv").csv({typed: true})
split3 = FileAttachment("data/splits/ward7_split.csv").csv({typed: true})
w7 = icu3.map((d, i) =&gt; ({...d, set: split3[i].set, fold: split3[i].fold,
                          sx: d.sofa + (((i * 7919) % 101) / 101 - 0.5) * 0.6}))
w7train = w7.filter(d =&gt; d.set === "train")
viewof cvModel = Inputs.radio(["Modelo da média", "Reta em função do SOFA"], {value: "Modelo da média", label: "Modelo"})
viewof cvPlay = Inputs.toggle({label: "Reproduzir", value: false})
viewof cvManual = Inputs.range([1, 6], {value: 1, step: 1, label: "Rodada (6 = combinar)"})



















































cvRound = {
  if (!cvPlay) { yield cvManual; return; }
  let r = 0;
  while (true) { yield (r % 6) + 1; r += 1; await Promises.delay(1400); }
}
cvFits = {
  const fitFn = rows =&gt; {
    const ys = rows.map(d =&gt; d.delta_creatinine_48h), my = d3.mean(ys);
    if (cvModel === "Modelo da média") return {a: my, b: 0};
    const xs = rows.map(d =&gt; d.sofa), mx = d3.mean(xs);
    const b = d3.sum(xs, (x, i) =&gt; (x - mx) * (ys[i] - my)) / d3.sum(xs, x =&gt; (x - mx) ** 2);
    return {a: my - b * mx, b};
  };
  return [1, 2, 3, 4, 5].map(v =&gt; {
    const f = fitFn(w7train.filter(d =&gt; d.fold !== v));
    const val = w7train.filter(d =&gt; d.fold === v);
    return {fold: v, a: f.a, b: f.b, mae: d3.mean(val, d =&gt; Math.abs(d.delta_creatinine_48h - (f.a + f.b * d.sofa)))};
  });
}
{
  const r = cvRound;
  const box = (label, sub, on, dashed) =&gt; html`&lt;div style="flex:1; min-width:58px; padding:6px 4px; text-align:center; border-radius:6px; font-size:0.82rem; border:1.5px ${dashed ? "dashed" : "solid"} ${on ? "var(--aihs-accent)" : "var(--aihs-border)"}; background:${on ? "var(--aihs-accent-soft)" : "transparent"}"&gt;&lt;strong&gt;${label}&lt;/strong&gt;&lt;br&gt;${sub}&lt;/div&gt;`;
  const cells = cvFits.map(f =&gt; box(`Partição ${f.fold}`,
    r === 6 ? `MAE ${f.mae.toFixed(3)}` : (r === f.fold ? "validação" : "ajuste"), r === f.fold || r === 6, false));
  const cv = d3.mean(cvFits, f =&gt; f.mae), se = d3.deviation(cvFits, f =&gt; f.mae) / Math.sqrt(5);
  if (r === 6 && window.aihs) window.aihs.complete("ch03-tryit-cv");
  return html`&lt;div style="display:flex; flex-wrap:wrap; gap:6px; margin:0.4rem 0"&gt;${cells}${box("Conjunto de teste", "250 · trancado", false, true)}&lt;/div&gt;
  &lt;p&gt;${r &lt; 6
    ? html`Rodada ${r}: ajustado nas partições ${[1, 2, 3, 4, 5].filter(v =&gt; v !== r).join(", ")}; MAE na partição ${r} = &lt;strong&gt;${cvFits[r - 1].mae.toFixed(3)}&lt;/strong&gt; mg/dL.`
    : html`MAE de validação cruzada = média das cinco = &lt;strong&gt;${cv.toFixed(3)}&lt;/strong&gt; mg/dL (erro padrão ${se.toFixed(3)}).`}&lt;/p&gt;`;
}























{
  const r = cvRound, lines = r === 6 ? cvFits : [cvFits[r - 1]];
  return Plot.plot({
    height: 290, grid: true, color: {type: "identity"},
    x: {label: "Escore SOFA na internação", domain: [-0.5, 18.5]},
    y: {label: "Variação da creatinina em 48 h (mg/dL)"},
    marks: [
      Plot.dot(w7train, {x: "sx", y: "delta_creatinine_48h", r: 1.8,
        fill: d =&gt; (r === 6 || d.fold === r) ? "#1f6f8b" : "#999",
        fillOpacity: d =&gt; (r === 6 || d.fold === r) ? 0.6 : 0.25}),
      ...lines.map(f =&gt; Plot.line([[0, f.a], [18, f.a + 18 * f.b]], {stroke: "#b35c00", strokeWidth: r === 6 ? 1.5 : 3}))
    ]
  });
}







Plot.plot({
  height: 170, grid: true, marginLeft: 50,
  x: {label: "Partição de validação", domain: [1, 2, 3, 4, 5], type: "band"},
  y: {label: "MAE (mg/dL)", domain: [0, 0.3]},
  marks: [
    Plot.barY(cvFits.filter(f =&gt; cvRound === 6 || f.fold &lt;= cvRound), {x: "fold", y: "mae", fill: "#1f6f8b", fillOpacity: 0.7}),
    cvRound === 6 ? Plot.ruleY([d3.mean(cvFits, f =&gt; f.mae)], {stroke: "#b35c00", strokeWidth: 2}) : null,
    Plot.ruleY([0])
  ]
})








Os cinco erros das partições não são idênticos; diferem em até alguns centésimos de mg/dL, porque algumas partições por acaso contêm pacientes mais fáceis que outras. Essa variação é exatamente o motivo pelo qual uma única divisão pode enganar, e pelo qual fazer a média entre as partições dá uma estimativa mais estável.
Quantas partições? Com um \(V\) maior, cada ajuste usa uma parte maior dos dados, de modo que a estimativa fica mais próxima do erro de um modelo treinado com todos eles; mas os ajustes se sobrepõem mais, os \(V\) erros ficam mais parecidos entre si e o custo computacional cresce. A validação cruzada leave-one-out (\(V = n\)) é o extremo: quase sem viés, mas variável e cara para modelos lentos. Cinco ou dez partições são o meio-termo habitual (James et al. 2021, cap. 5; Hastie, Tibshirani, e Friedman 2009, cap. 7). Dois refinamentos são comuns. A validação cruzada repetida executa o procedimento inteiro de novo com várias atribuições aleatórias das partições e faz a média, o que estabiliza ainda mais a estimativa. As partições estratificadas mantêm parecida em todas as partições a proporção de um desfecho (por exemplo, LRA sim/não) (Kuhn e Johnson 2013, cap. 4).
As partições precisam respeitar a estrutura dos dados. Se um paciente contribui com várias linhas, como um participante do HomeBeat com uma linha por dia, todas as linhas dessa pessoa precisam ficar na mesma partição; caso contrário, o modelo é validado em parte nas mesmas pessoas em que foi ajustado. A mesma lógica, aplicada aos hospitais, dá a validação cruzada deixando um hospital de fora (leave-one-site-out): ajustar em três hospitais da UTI Ala 7, testar no quarto e fazer o rodízio. É a validação interna-externa da Seção 3.2, e nós a usamos no final deste capítulo.

Com validação cruzada com cinco partições nos 1.000 pacientes de treino da UTI Ala 7, quantas vezes o modelo é ajustado, e com quantos pacientes de cada vez?

Uma vez, com 1.000 pacientes Isso é um único ajuste em todo o conjunto de treino: dá um modelo, mas nenhuma estimativa honesta do erro.
Cinco vezes, com 800 pacientes de cada vez Correto. Cada rodada deixa de fora uma partição de 200 e ajusta nos 800 restantes. (Depois que a validação cruzada orientou as escolhas, o modelo escolhido costuma ser reajustado mais uma vez com todos os 1.000.)
Cinco vezes, com 200 pacientes de cada vez É o contrário: cada ajuste usa quatro partições (800 pacientes) e é validado na quinta (200).
1.000 vezes, com 999 pacientes de cada vez Isso é a validação cruzada leave-one-out, o caso \(V = n\).

3.7 \(k\) vizinhos mais próximos: um primeiro método de aprendizado
Até aqui, nossos modelos foram médias e retas. Eis uma ideia diferente, próxima do modo como os clínicos raciocinam com base na experiência: para prever o que vai acontecer com Aoife, olhe para os pacientes anteriores que eram mais parecidos com ela e veja o que aconteceu com eles.

Definição 3.5 (\(k\) vizinhos mais próximos) O método dos \(k\) vizinhos mais próximos (\(k\)NN, do inglês \(k\)-nearest neighbours) prevê o desfecho de uma nova instância \(\mathbf{x}\) encontrando as \(k\) instâncias de treino mais próximas dela, o conjunto \(N_k(\mathbf{x})\), e fazendo a média dos seus desfechos (para um desfecho numérico) ou uma votação (para uma categoria):
\[
\hat y(\mathbf{x}) = \frac{1}{k}\sum_{i \in N_k(\mathbf{x})} y_i .
\qquad(3.7)\]
“Mais próximas” é medido por uma distância entre vetores de atributos, em geral a distância euclidiana entre atributos padronizados (Cover e Hart 1967; James et al. 2021, cap. 2).

O \(k\)NN tem uma propriedade incomum: não tem etapa de ajuste. O “treinamento” consiste em guardar os pacientes de treino; todo o trabalho acontece no momento da predição. Dois ingredientes exigem cuidado.
Distância. Na UTI Ala 7, usamos dois preditores, o escore SOFA e a creatinina basal, e medimos o quanto dois pacientes estão afastados com a distância comum em linha reta (euclidiana) no plano formado pelos dois. O Capítulo 10 é dedicado às distâncias e ao que acontece com elas quando há muitos preditores; por enquanto, o plano basta.
Escala. O SOFA vai de 0 a 18 pontos; a creatinina basal, de cerca de 0,4 a 3 mg/dL. Medido em valores brutos, um ponto de SOFA contaria tanto quanto um mg/dL inteiro de creatinina, só por causa das unidades. Por isso cada preditor é padronizado: subtrai-se a média de treino e divide-se o resultado pelo desvio padrão de treino, o que coloca os dois em uma escala comparável. Com a padronização, as predições não dependem das unidades. Sem ela, dependem: se a creatinina for registrada em µmol/L (1 mg/dL = 88,4 µmol/L), seus números grandes dominam a distância e o MAE de validação cruzada do \(k\)NN sem padronização piora de 0,181 para 0,189 mg/dL, enquanto o \(k\)NN padronizado dá 0,179 em qualquer das duas unidades. Repare na palavra treino: as médias e os desvios padrão são aprendidos somente nas linhas de treino (nas partições de ajuste, durante a validação cruzada), senão a própria padronização vaza (Seção 3.6).
O número de vizinhos \(k\) controla a flexibilidade. Com \(k = 1\), cada predição copia um único paciente anterior: o modelo acompanha cada acidente dos dados, o extremo de variância alta da Definição 1.8. Seu erro de treino é próximo de zero, porque cada paciente de treino é (quase) o seu próprio vizinho mais próximo; na UTI Ala 7, ele é de 0,072 mg/dL. Seu erro de validação cruzada é de 0,254, pior que o do modelo da média. À medida que \(k\) cresce, as predições passam a ser médias de mais pacientes e ficam mais suaves; com \(k\) igual a todo o conjunto de treino, toda predição é a média de treino, o extremo de viés alto. Em algum ponto intermediário está o melhor equilíbrio, e só dados que o modelo não viu podem nos dizer onde.

Pacientes como Aoife. O fundo mostra a predição do \(k\)NN para a variação da creatinina em 48 horas em cada combinação de SOFA e creatinina basal; os pontos cinza são os 1.000 pacientes de treino e os três pontos rotulados são os pacientes desta noite. Os pontos circulados são os \(k\) vizinhos mais próximos de Aoife. O gráfico de baixo mostra o erro de treino e o erro de validação cruzada com cinco partições para cada \(k\). Mova \(k\) e veja o mapa passar de irregular a suave. Meta: encontrar um \(k\) cujo MAE de validação cruzada fique a até 0,001 mg/dL do menor possível.

knnCurve = FileAttachment("data/precomputed/ch03/knn_curve.csv").csv({typed: true})
knnSummary = FileAttachment("data/precomputed/ch03/summary.json").json()
tonight3 = FileAttachment("data/ward7_tonight.csv").csv({typed: true})
viewof kNN = Inputs.range([1, 150], {value: 1, step: 1, label: "Número de vizinhos k"})






























knnPrep = {
  const tr = w7train, K = 150;
  const xs = tr.map(d =&gt; d.sofa), cs = tr.map(d =&gt; d.baseline_creat), ys = tr.map(d =&gt; d.delta_creatinine_48h);
  const mx = d3.mean(xs), sx = d3.deviation(xs), mc = d3.mean(cs), sc = d3.deviation(cs);
  const zx = xs.map(x =&gt; (x - mx) / sx), zc = cs.map(c =&gt; (c - mc) / sc);
  const neigh = (s, c) =&gt; {
    const a = (s - mx) / sx, b = (c - mc) / sc;
    const d = zx.map((z, i) =&gt; ({i, d: (z - a) ** 2 + (zc[i] - b) ** 2}));
    d.sort((p, q) =&gt; p.d - q.d || p.i - q.i);
    const cum = new Float64Array(K); let acc = 0;
    for (let j = 0; j &lt; K; j++) { acc += ys[d[j].i]; cum[j] = acc; }
    return {cum, idx: d.slice(0, K).map(e =&gt; e.i)};
  };
  const c0 = 0.4, c1 = 2.6, ny = 28, cs0 = (c1 - c0) / ny, grid = [];
  for (let s = 0; s &lt;= 18; s++) for (let b = 0; b &lt; ny; b++) {
    const c = c0 + (b + 0.5) * cs0;
    grid.push({x1: s - 0.5, x2: s + 0.5, y1: c0 + b * cs0, y2: c0 + (b + 1) * cs0, cum: neigh(s, c).cum});
  }
  const pts = tonight3.map(p =&gt; ({name: p.name.split(" ")[0], sofa: p.sofa, creat: p.baseline_creat, ...neigh(p.sofa, p.baseline_creat)}));
  const jit = tr.map((d, i) =&gt; ({sx: d.sofa + (((i * 7919) % 101) / 101 - 0.5) * 0.6, c: d.baseline_creat}));
  return {grid, pts, jit};
}







