    .attr("fill", "currentColor").attr("font-size", 12).text("Variação da creatinina (mg/dL)");
  const clip = (lo, hi) =&gt; v =&gt; Math.max(lo, Math.min(hi, v));
  const line = (f, cls) =&gt; svg.append("line").attr("stroke", "currentColor").attr("stroke-width", cls === "with" ? 2.5 : 1.6)
    .attr("stroke-dasharray", cls === "with" ? null : "6,4").attr("opacity", cls === "with" ? 1 : 0.6);
  const lWith = line(null, "with"), lWithout = line(null, "without");
  const seg = svg.append("line").attr("stroke", "var(--aihs-bad)").attr("stroke-width", 1.5);
  svg.append("g").selectAll("circle").data(base).join("circle")
    .attr("cx", d =&gt; xs(d.x)).attr("cy", d =&gt; ys(d.y)).attr("r", 4.5)
    .attr("fill", "var(--aihs-accent)").attr("fill-opacity", 0.75);
  const dot = svg.append("circle").attr("r", 10).attr("fill", "var(--aihs-bad)")
    .attr("stroke", "currentColor").attr("stroke-width", 1.5).style("cursor", "grab")
