  const out = html`&lt;div class="aihs-feedback" aria-live="polite"&gt;&lt;/div&gt;`;
  function update() {
    const all = base.concat([red]), f = ols(all), g = ols(base);
    const n = all.length, k = 2;
    const res = all.map(q =&gt; q.y - (f.b0 + f.b1 * q.x));
    const s2 = d3.sum(res, r =&gt; r * r) / (n - k);
    const h = 1 / n + (red.x - f.mx) ** 2 / f.sxx;
    const e = red.y - (f.b0 + f.b1 * red.x);
    const D = e * e / (k * s2) * h / ((1 - h) ** 2);
    const rs = e / Math.sqrt(s2 * (1 - h));
    const X0 = 0, X1 = 24;
    lWith.attr("x1", xs(X0)).attr("y1", ys(f.b0)).attr("x2", xs(X1)).attr("y2", ys(f.b0 + f.b1 * X1));
