      : hiLev && !bigRes ? "alavancagem alta, mas sobre a reta: inofensivo"
      : bigRes && !hiLev ? "um outlier com alavancagem baixa: a reta quase não se move"
      : "um paciente comum";
    out.innerHTML = `Alavancagem &lt;strong&gt;${h.toFixed(3)}&lt;/strong&gt; (sinalização acima de ${(2 * k / n).toFixed(3)}) ·
