gt = {
  const fx = gtX, fy = gtY === gtX ? (gtX === "sofa" ? "baseline_creat" : "sofa") : gtY;
  const rows = icuT.map(d =&gt; ({x: d[fx], y: d[fy], t: d.delta_creatinine_48h, set: d.set}));
  const train = rows.filter(d =&gt; d.set === "train"), test = rows.filter(d =&gt; d.set === "test");
  const minLeaf = 10, maxD = 8;
  function grow(idx, depth, box) {
    const n = idx.length;
    let tot = 0, totss = 0;
    for (const i of idx) { tot += train[i].t; totss += train[i].t ** 2; }
    const node = {n, mean: tot / n, depth, box};
    if (depth &gt;= maxD || n &lt; 2 * minLeaf) return node;
    let best = null;
    for (const f of ["x", "y"]) {
      const s = idx.slice().sort((a, b) =&gt; train[a][f] - train[b][f]);
      let ls = 0, lss = 0;
      for (let k = 0; k &lt; n - 1; k++) {
        const v = train[s[k]].t; ls += v; lss += v * v;
        const nl = k + 1, nr = n - nl;
        if (nl &lt; minLeaf || nr &lt; minLeaf) continue;
        const a = train[s[k]][f], b = train[s[k + 1]][f];
        if (a === b) continue;
        const sse = (lss - ls * ls / nl) + ((totss - lss) - (tot - ls) ** 2 / nr);
        if (!best || sse &lt; best.sse) best = {sse, f, thr: (a + b) / 2, k, s};
      }
    }
    if (!best) return node;
    node.f = best.f; node.thr = best.thr;
    const bl = {...box}, br = {...box};
    if (best.f === "x") { bl.x2 = best.thr; br.x1 = best.thr; } else { bl.y2 = best.thr; br.y1 = best.thr; }
    node.left = grow(best.s.slice(0, best.k + 1), depth + 1, bl);
    node.right = grow(best.s.slice(best.k + 1), depth + 1, br);
    return node;
  }
  const [x1, x2] = d3.extent(rows, d =&gt; d.x), [y1, y2] = d3.extent(rows, d =&gt; d.y);
  const root = grow(d3.range(train.length), 0, {x1, x2, y1, y2});
  const predict = (node, p, D) =&gt; (node.f && node.depth &lt; D) ? predict(p[node.f] &lt;= node.thr ? node.left : node.right, p, D) : node.mean;
  const leaves = (node, D) =&gt; (node.f && node.depth &lt; D) ? [...leaves(node.left, D), ...leaves(node.right, D)] : [node];
  const curve = d3.range(0, maxD + 1).flatMap(D =&gt; [
    {D, set: "treino", mae: d3.mean(train, p =&gt; Math.abs(p.t - predict(root, p, D)))},
    {D, set: "teste", mae: d3.mean(test, p =&gt; Math.abs(p.t - predict(root, p, D)))}]);
  const testc = curve.filter(c =&gt; c.set === "teste");
  const bestD = testc.reduce((a, c) =&gt; c.mae &lt; a.mae ? c : a).D;
  const label = k =&gt; [...gtChoices].find(e =&gt; e[1] === k)[0];
  return {root, train, leaves, curve, bestD, fx, fy, lx: label(fx), ly: label(fy)};
}







