betaTools = {
  const cf = [0.99999999999980993, 676.5203681218851, -1259.1392167224028, 771.32342877765313,
              -176.61502916214059, 12.507343278686905, -0.13857109526572012, 9.9843695780195716e-6, 1.5056327351493116e-7];
  function lgamma(z) {
    if (z &lt; 0.5) return Math.log(Math.PI / Math.sin(Math.PI * z)) - lgamma(1 - z);
    z -= 1; let x = cf[0]; for (let i = 1; i &lt; 9; i++) x += cf[i] / (z + i);
    const t = z + 7.5; return 0.5 * Math.log(2 * Math.PI) + (z + 0.5) * Math.log(t) - t + Math.log(x);
  }
  const grid = d3.range(0.00025, 1, 0.0005);
  function pdf(a, b) { const lb = lgamma(a) + lgamma(b) - lgamma(a + b);
    return grid.map(x =&gt; Math.exp((a - 1) * Math.log(x) + (b - 1) * Math.log(1 - x) - lb)); }
  function quant(dens, p) { let c = 0; const tot = d3.sum(dens);
    for (let i = 0; i &lt; grid.length; i++) { c += dens[i] / tot; if (c &gt;= p) return grid[i]; } return 1; }
  return {grid, pdf, quant};
}
