kmTraj = {
  const rnd = mulberry32(startNo * 7919 + kK * 104729), pts = wear2, n = pts.length;
  const pick = [];
  while (pick.length &lt; kK) { const i = Math.floor(rnd() * n); if (!pick.includes(i)) pick.push(i); }
  let C = pick.map(i =&gt; [pts[i].x, pts[i].y]), labels = null;
  const states = [{phase: "start", C, labels: null}];
  for (let it = 0; it &lt; 80; it++) {
    const nl = pts.map(p =&gt; { let best = 0, bd = Infinity;
      C.forEach((c, k) =&gt; { const d = (p.x - c[0]) ** 2 + (p.y - c[1]) ** 2; if (d &lt; bd) { bd = d; best = k; } });
      return best; });
    const changed = labels ? nl.filter((l, i) =&gt; l !== labels[i]).length : n;
    labels = nl;
    states.push({phase: "assign", C, labels, changed});
    if (changed === 0) break;
    const newC = C.map((c, k) =&gt; { const m = pts.filter((p, i) =&gt; labels[i] === k);
      return m.length ? [d3.mean(m, p =&gt; p.x), d3.mean(m, p =&gt; p.y)] : c; });
    states.push({phase: "update", C: newC, prev: C, labels});
    C = newC;
  }
  for (const s of states) if (s.labels) s.wss = d3.sum(pts, (p, i) =&gt; (p.x - s.C[s.labels[i]][0]) ** 2 + (p.y - s.C[s.labels[i]][1]) ** 2);
  return states;
}
