viewof iceCentre = Inputs.toggle({label: "Centralizar as curvas (c-ICE)", value: false})
viewof icePat = Inputs.range([1, 171], {value: 1, step: 1, label: "Destacar o paciente número"})












































iceData = {
  const f = ice.features[iceFeat], grid = f.grid, M = ice.ice[iceModel][iceFeat];
  const label = iceLab[iceFeat];
  const adj = c =&gt; iceCentre ? c[0] : 0;
  const rows = [];
  M.forEach((c, i) =&gt; c.forEach((v, k) =&gt; rows.push({pid: i + 1, x: grid[k], y: v - adj(c)})));
  const pd = grid.map((x, k) =&gt; ({x, y: d3.mean(M, c =&gt; c[k] - adj(c))}));
  const hl = grid.map((x, k) =&gt; ({x, y: M[icePat - 1][k] - adj(M[icePat - 1])}));
  const last = grid.length - 1;
  const spread = d3.deviation(M, c =&gt; c[last] - c[0]);
