14.4 Aprender com a experiência: Q-learning
A iteração de valor precisa das probabilidades de transição da Tabela 14.2. Para um paciente real, ninguém as tem. Um agente consegue encontrar uma boa política apenas agindo e observando o que acontece? É isso que faz o aprendizado por reforço livre de modelo (model-free), e o Q-learning é o seu algoritmo clássico (Watkins e Dayan 1992).

Definição 14.8 (Q-learning) O Q-learning mantém uma tabela de estimativas \(\hat Q(s, a)\), uma para cada estado e ação, todas começando em zero. Depois de cada passo — estado \(s\), ação \(a\), recompensa \(r\), próximo estado \(s'\) — ele move a estimativa em direção a um alvo mais bem informado:
\[
\hat Q(s, a) \leftarrow \hat Q(s, a) + \eta\,\Bigl[\, \underbrace{r + \gamma \max_{a'} \hat Q(s', a')}_{\text{alvo}} - \hat Q(s, a) \,\Bigr],
\qquad(14.5)\]
em que \(\eta\) é o tamanho do passo. As ações costumam ser escolhidas de forma \(\epsilon\)-gulosa a partir da tabela atual. Se todos os pares estado–ação continuarem sendo experimentados e o tamanho do passo diminuir de forma adequada, as estimativas convergem para \(Q^*\) (Watkins e Dayan 1992; Sutton e Barto 2018, cap. 6).

Observe a forma: nova estimativa = estimativa antiga + passo × (alvo − estimativa antiga), como na Equação 14.1. O alvo é uma versão de um passo da equação de otimalidade de Bellman: a recompensa efetivamente recebida mais o valor descontado da melhor ação no estado efetivamente alcançado, segundo a estimativa atual. Nenhuma probabilidade de transição aparece; o ambiente fornece amostras delas, um passo de cada vez. O \(\max\) no alvo é o que torna o Q-learning off-policy (fora da política): ele aprende o valor de agir de forma gulosa mesmo enquanto está explorando, de modo que os passos exploratórios não estragam o que ele aprende.
Um passo resolvido. Suponha que o agente esteja em “10–14, baixa”, com estimativas atuais de \(-0.4\), \(0.8\) e \(1.6\) para reduzir, manter e aumentar. Ele aumenta a velocidade; a glicose cai para 6–10 (recompensa \(+1\)) e o próximo estado é “6–10, média”, cujas estimativas são \(2.1\), \(2.9\) e \(1.2\). Com \(\eta = 0.1\) e \(\gamma = 0.9\), o alvo é \(1 + 0.9 \times 2.9 = 3.61\), o erro é \(3.61 - 1.6 = 2.01\) e a estimativa passa a \(1.6 + 0.1 \times 2.01 = 1.801\). Você vai programar esse passo na missão abaixo.

Veja um agente aprender a dosar. Cada célula é um estado do problema de brinquedo: faixa de glicose (linhas) e velocidade de infusão (colunas). A seta mostra a ação que o agente considera melhor no momento (← reduzir, • manter, → aumentar); a cor mostra quanto o agente espera acumular a partir daquele estado (azul é bom, vermelho é ruim). O contorno grosso marca onde a paciente simulada está agora. Pressione Um passo algumas vezes e leia a atualização logo abaixo — é a Equação 14.5 com números. Depois treine por centenas de episódios (um episódio são 24 horas: 12 passos a partir de um estado inicial aleatório). Um ✓ marca um estado em que a escolha do agente é tão boa quanto a da política ótima da Tabela 14.3 (com tolerância de 0,05). Meta: pelo menos 18 dos 20 estados com ✓ depois de 50 ou mais episódios. Depois coloque ε em 0 e reinicie: o que acontece sem exploração?

mdpSpec = FileAttachment("data/precomputed/ch14/insulin_mdp.json").json()







mdp = {
  const M = mdpSpec.moves, gamma = mdpSpec.gamma, S = 20, A = 3;
  const sid = (g, r) =&gt; r * 5 + g, band = s =&gt; s % 5, rate = s =&gt; Math.floor(s / 5);
  const bandLab = ["&lt; 4", "4–6", "6–10", "10–14", "&gt; 14"], rateLab = ["desligada", "baixa", "média", "alta"];
  function next(s, a, rew) {                 // a: 0 reduzir, 1 manter, 2 aumentar
    const r2 = Math.min(3, Math.max(0, rate(s) + a - 1)), g = band(s), out = [];
    for (let m = 0; m &lt; 3; m++) { const g2 = Math.min(4, Math.max(0, g + m - 1)); out.push([M[r2][m], sid(g2, r2), rew[g2]]); }
    return out;
  }
  function solve(rew) {
    let V = new Array(S).fill(0), Q = null;
    for (let k = 0; k &lt; 3000; k++) {
      Q = d3.range(S).map(s =&gt; d3.range(A).map(a =&gt; d3.sum(next(s, a, rew), ([p, s2, r]) =&gt; p * (r + gamma * V[s2]))));
      const V2 = Q.map(q =&gt; Math.max(...q)), diff = d3.max(V2, (v, i) =&gt; Math.abs(v - V[i]));
      V = V2; if (diff &lt; 1e-10) break;
    }
    const policy = Q.map(q =&gt; q.indexOf(Math.max(...q)));
    return {V, Q, policy};
  }
  function evaluate(policy) {                // ocupação exata em 24 horas a partir de glicose 10-14, infusão desligada
    let d = new Array(S).fill(0); d[sid(3, 0)] = 1; const acc = {inRange: 0, hypo: 0, hyper: 0};
    for (let t = 0; t &lt; 12; t++) {
      const d2 = new Array(S).fill(0);
      for (let s = 0; s &lt; S; s++) if (d[s] &gt; 0) for (const [p, s2] of next(s, policy[s], [0, 0, 0, 0, 0])) d2[s2] += d[s] * p;
      d = d2;
      for (let s = 0; s &lt; S; s++) { const g = band(s); if (g === 2) acc.inRange += d[s] / 12; if (g === 0) acc.hypo += d[s] / 12; if (g &gt;= 3) acc.hyper += d[s] / 12; }
    }
    return acc;
  }
  const arrows = ["←", "•", "→"];
  // Com a infusão 'desligada', reduzir não muda nada, e na 'alta' aumentar também não: mostre-os como 'manter'.
  const eff = (s, a) =&gt; (rate(s) === 0 && a === 0) || (rate(s) === 3 && a === 2) ? 1 : a;
  // Desenha a grade 5 x 4 de estados. cellFn(s) -&gt; {fill, label, corner, current, faded}
  function grid(cellFn, aria) {
    const cw = 104, ch = 58, x0 = 92, y0 = 44, W = x0 + 4 * cw + 12, H = y0 + 5 * ch + 34;
    const svg = d3.create("svg").attr("viewBox", `0 0 ${W} ${H}`).attr("class", "aihs-svg")
      .attr("role", "img").attr("aria-label", aria).style("max-width", "560px");
    rateLab.forEach((r, j) =&gt; svg.append("text").attr("x", x0 + j * cw + cw / 2).attr("y", y0 - 10).attr("text-anchor", "middle").attr("font-size", 13).text(r));
    svg.append("text").attr("x", x0 + 2 * cw).attr("y", 14).attr("text-anchor", "middle").attr("font-size", 13).attr("font-weight", 700).text("Velocidade de infusão de insulina →");
    for (let g = 4; g &gt;= 0; g--) {
      const row = 4 - g;
      svg.append("text").attr("x", x0 - 8).attr("y", y0 + row * ch + ch / 2 + 4).attr("text-anchor", "end").attr("font-size", 13)
        .attr("font-weight", g === 2 ? 700 : 400).text(bandLab[g] + (g === 2 ? " ★" : ""));
      for (let r = 0; r &lt; 4; r++) {
        const s = sid(g, r), c = cellFn(s), x = x0 + r * cw, y = y0 + row * ch;
        svg.append("rect").attr("x", x + 2).attr("y", y + 2).attr("width", cw - 4).attr("height", ch - 4).attr("rx", 6)
          .attr("fill", c.fill).style("stroke", c.current ? "var(--aihs-accent, #1f6f8b)" : "currentColor")
          .attr("stroke-width", c.current ? 4 : 0.6).attr("opacity", c.faded ? 0.55 : 1);
        svg.append("text").attr("x", x + cw / 2).attr("y", y + ch / 2 + 8).attr("text-anchor", "middle").attr("font-size", 24)
          .attr("font-weight", 700).style("fill", "#111").text(c.label);
        if (c.corner) svg.append("text").attr("x", x + cw - 9).attr("y", y + 17).attr("text-anchor", "end").attr("font-size", 12).style("fill", "#111").text(c.corner);
        if (c.left) svg.append("text").attr("x", x + 9).attr("y", y + 17).attr("font-size", 11).style("fill", "#333").text(c.left);
      }
    }
    svg.append("text").attr("x", 8).attr("y", y0 + 5 * ch + 24).attr("font-size", 12).attr("class", "muted").text("Linhas: glicose (mmol/L), ★ = faixa-alvo.");
    return svg.node();
  }
  const colour = d3.scaleLinear().domain([-12, 0, 5]).range(["#e8a39b", "#f2f2f2", "#8fc1d4"]).clamp(true);
  return {S, A, sid, band, rate, bandLab, rateLab, next, solve, evaluate, arrows, eff, grid, colour, gamma};
}







qlStepper = {
  const {S, A, band, rate, bandLab, rateLab, next, solve, arrows, eff, grid, colour, gamma} = mdp;
  const rew = mdpSpec.presets.clinical, opt = solve(rew), steps = 12;
  function mulberry32(a) { return function() { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a &gt;&gt;&gt; 15, 1 | a); t = t + Math.imul(t ^ t &gt;&gt;&gt; 7, 61 | t) ^ t; return ((t ^ t &gt;&gt;&gt; 14) &gt;&gt;&gt; 0) / 4294967296; }; }
  const argmax = q =&gt; { let b = 0; for (let i = 1; i &lt; q.length; i++) if (q[i] &gt; q[b]) b = i; return b; };
  const lab = s =&gt; `${bandLab[band(s)]} | ${rateLab[rate(s)]}`;
  const actName = ["reduzir", "manter", "aumentar"];
  let rnd, Q, s, t, ep, last, done = false;
