      &lt;button type="button" class="btn btn-sm btn-outline-primary" data-n="50"&gt;+50 episódios&lt;/button&gt;
      &lt;button type="button" class="btn btn-sm btn-outline-primary" data-n="500"&gt;+500 episódios&lt;/button&gt;
      &lt;button type="button" class="btn btn-sm btn-outline-secondary" data-n="reset"&gt;Reiniciar&lt;/button&gt;
    &lt;/div&gt;
    &lt;div style="display:flex;flex-wrap:wrap;gap:1.2rem;font-size:0.9rem;align-items:center"&gt;
      &lt;label&gt;Exploração ε &lt;input type="range" min="0" max="0.5" step="0.05" value="0.2" name="eps" aria-label="Taxa de exploração épsilon"&gt; &lt;output name="epsOut"&gt;0.20&lt;/output&gt;&lt;/label&gt;
      &lt;label&gt;Tamanho do passo η &lt;input type="range" min="0.05" max="0.5" step="0.05" value="0.1" name="eta" aria-label="Tamanho do passo eta"&gt; &lt;output name="etaOut"&gt;0.10&lt;/output&gt;&lt;/label&gt;
      &lt;label&gt;&lt;input type="checkbox" name="showOpt"&gt; mostrar a ação ótima (pequena, no canto superior esquerdo)&lt;/label&gt;
    &lt;/div&gt;
    &lt;div class="ql-grid"&gt;&lt;/div&gt;
    &lt;div class="ql-log" style="font-size:0.9rem;min-height:4.5em"&gt;&lt;/div&gt;
  &lt;/div&gt;`;
  const q = sel =&gt; root.querySelector(sel);
  const epsIn = q('input[name="eps"]'), etaIn = q('input[name="eta"]'), showOpt = q('input[name="showOpt"]');
  function render() {
    q('output[name="epsOut"]').textContent = (+epsIn.value).toFixed(2);
    q('output[name="etaOut"]').textContent = (+etaIn.value).toFixed(2);
    const g = grid(x =&gt; {
      const untouched = Q[x].every(v =&gt; v === 0), b = argmax(Q[x]);
      return {fill: colour(Math.max(...Q[x])), label: untouched ? "·" : arrows[eff(x, b)], current: x === s,
              corner: opt.Q[x][b] &gt;= opt.V[x] - 0.05 && !untouched ? "✓" : "", faded: untouched,
              left: showOpt.checked ? "ótima " + arrows[eff(x, opt.policy[x])] : ""};
    }, "Grade de 20 estados mostrando a ação que o agente em aprendizado prefere atualmente em cada um.");
    q(".ql-grid").replaceChildren(g);
    const no = nearOpt(), hit = ep &gt;= 50 && no &gt;= 18;
