    if (r.set !== "train") continue;
    const w = ["&lt;s&gt;", ...r.text.split(" "), "&lt;/s&gt;"];
    for (let i = 1; i &lt; w.length; i++) {
      vocab.add(w[i]);
      const a = w[i - 1], b = w[i];
      if (!counts.has(a)) counts.set(a, new Map());
